        en: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#B22234"/><rect y="2" width="20" height="2" fill="#fff"/><rect y="6" width="20" height="2" fill="#fff"/><rect y="10" width="20" height="2" fill="#fff"/><rect width="8" height="7.5" fill="#3C3B6E"/><circle cx="1.5" cy="1.2" r="0.4" fill="#fff"/><circle cx="3" cy="2" r="0.4" fill="#fff"/><circle cx="4.5" cy="1.2" r="0.4" fill="#fff"/><circle cx="6" cy="2" r="0.4" fill="#fff"/><circle cx="1.5" cy="3.2" r="0.4" fill="#fff"/><circle cx="3" cy="4" r="0.4" fill="#fff"/><circle cx="4.5" cy="3.2" r="0.4" fill="#fff"/><circle cx="6" cy="4" r="0.4" fill="#fff"/><circle cx="1.5" cy="5.2" r="0.4" fill="#fff"/><circle cx="3" cy="6" r="0.4" fill="#fff"/><circle cx="4.5" cy="5.2" r="0.4" fill="#fff"/><circle cx="6" cy="6" r="0.4" fill="#fff"/></svg>`,
        ru: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#fff"/><rect y="4.67" width="20" height="4.66" fill="#0035A9"/><rect y="9.33" width="20" height="4.67" fill="#D52B1E"/></svg>`,
        uz: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#1EB53A"/><rect width="20" height="4.67" fill="#009FCA"/><rect y="9.33" width="20" height="4.67" fill="#009FCA"/><rect y="4.67" width="20" height="4.66" fill="#fff"/></svg>`,
        ja: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#fff"/><circle cx="10" cy="7" r="4" fill="#BC002D"/></svg>`,
        zh: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#DE2910"/><polygon points="3,1 3.6,2.9 5.6,2.9 4,4 4.6,5.9 3,4.8 1.4,5.9 2,4 0.4,2.9 2.4,2.9" transform="translate(0.5,0.5) scale(0.95)" fill="#FFDE00"/><polygon points="1.5,0 1.9,1.2 3.1,1.2 2.1,1.9 2.5,3.1 1.5,2.4 0.5,3.1 0.9,1.9 -0.1,1.2 1.1,1.2" transform="translate(8,0.5)" fill="#FFDE00"/><polygon points="1.5,0 1.9,1.2 3.1,1.2 2.1,1.9 2.5,3.1 1.5,2.4 0.5,3.1 0.9,1.9 -0.1,1.2 1.1,1.2" transform="translate(10,2.5)" fill="#FFDE00"/><polygon points="1.5,0 1.9,1.2 3.1,1.2 2.1,1.9 2.5,3.1 1.5,2.4 0.5,3.1 0.9,1.9 -0.1,1.2 1.1,1.2" transform="translate(10,5.5)" fill="#FFDE00"/><polygon points="1.5,0 1.9,1.2 3.1,1.2 2.1,1.9 2.5,3.1 1.5,2.4 0.5,3.1 0.9,1.9 -0.1,1.2 1.1,1.2" transform="translate(8,7.5)" fill="#FFDE00"/></svg>`,
        fr: `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 20 14" width="20" height="14" style="border-radius:2px;flex-shrink:0;vertical-align:middle" class="flag-icon"><rect width="20" height="14" fill="#ED2939"/><rect width="13.33" height="14" fill="#fff"/><rect width="6.67" height="14" fill="#002395"/></svg>`,
